class Valves(BaseModel):
    """Admin / instance-level configuration edited in the plugin's settings."""

    tenki_api_key: str = Field(
        default="",
        description="Required. Your Tenki API key. Stored server-side; never logged.",
    )
    tenki_api_endpoint: str = Field(
        default="https://api.tenki.cloud",
        description="Tenki API endpoint. Override for self-hosted/staging.",
    )
    tenki_workspace_id: str = Field(
        default="",
        description="Optional Tenki workspace ID. Uses the account default when empty.",
    )
    default_language: Literal["python", "shell"] = Field(
        default="python",
        description="Language used when the caller does not specify one.",
    )
    cpu_cores: int = Field(default=1, ge=1, le=16, description="Sandbox vCPU count (1-16).")
    memory_mb: int = Field(
        default=512, ge=128, le=65536, description="Sandbox memory in MiB (128-65536, even)."
    )
    disk_size_gb: int = Field(
        default=5, ge=5, le=100, description="Sandbox disk size in GiB (5-100)."
    )
    timeout_seconds: int = Field(
        default=300, ge=1, le=600, description="Max execution time per run."
    )
    network_egress: bool = Field(
        default=False,
        description="Allow sandbox outbound network access. Off by default for safety.",
    )
    sandbox_image: str = Field(
        default="",
        description="Optional Tenki image/template ref providing python3 + bash.",
    )
    max_concurrent_executions: int = Field(
        default=5, ge=1, description="Max simultaneous sandboxes per instance."
    )
    max_output_bytes: int = Field(
        default=100_000, ge=1_000, description="Truncation cap for captured output."
    )

    @field_validator("memory_mb")
    @classmethod
    def _memory_even(cls, value: int) -> int:
        # Tenki requires memory aligned to 2 MiB; fail fast with a clear message.
        if value % 2 != 0:
            raise ValueError("memory_mb must be aligned to 2 MiB (an even number)")
        return value


class UserValves(BaseModel):
    """Per-user override. A user's own key takes precedence over the admin key."""

    tenki_api_key: str = Field(
        default="",
        description="Your own Tenki API key. If set, overrides the admin key for your executions.",
    )


def _user_key(__user__: dict | None) -> str:
    """Extract a per-user Tenki key from the Open WebUI ``__user__`` payload.

    ``__user__["valves"]`` may be a ``UserValves`` instance or a plain dict.
    """
    if not __user__:
        return ""
    valves = __user__.get("valves") if isinstance(__user__, dict) else None
    if valves is None:
        return ""
    if isinstance(valves, dict):
        return (valves.get("tenki_api_key") or "").strip()
    return (getattr(valves, "tenki_api_key", "") or "").strip()


def resolve_effective_key(valves: Valves, __user__: dict | None = None) -> str:
    """Effective credential: per-user key wins, else the admin key. ``""`` if none."""
    return _user_key(__user__) or (valves.tenki_api_key or "").strip()


def _fenced(text: str) -> str:
    """Wrap untrusted text in a code fence longer than any backtick run inside it,
    so the text cannot break out of the block and render as live markdown."""
    longest = run = 0
    for ch in text:
        run = run + 1 if ch == "`" else 0
        longest = max(longest, run)
    fence = "`" * max(3, longest + 1)
    return f"{fence}\n{text}\n{fence}"


class ExecutionResult(BaseModel):
    """Outcome of a single code execution. Rendered for the Tool and the Action."""

    stdout: str = ""
    stderr: str = ""
    result: str = ""
    images: list[str] = Field(default_factory=list)  # base64 "data:image/...;base64,..." URIs
    exit_code: int | None = None
    duration_ms: int = 0
    timed_out: bool = False
    truncated: bool = False
    error: str | None = None  # set only when execution never ran (config/provision failure)

    def _duration_text(self) -> str:
        return f"{self.duration_ms / 1000:.1f}s"

    def to_model_text(self) -> str:
        """Compact text the LLM can read and iterate on (used by the Tool)."""
        if self.error:
            return f"Error: {self.error}"

        lines: list[str] = []
        if self.timed_out:
            lines.append(f"[timed out after {self._duration_text()}]")
        else:
            lines.append(f"[exit={self.exit_code}, {self._duration_text()}]")

        stdout_label = "partial stdout:" if self.timed_out else "stdout:"
        if self.stdout:
            lines.append(f"{stdout_label}\n{self.stdout}")
        if self.stderr:
            lines.append(f"stderr:\n{self.stderr}")
        if self.result:
            lines.append(f"result:\n{self.result}")
        if self.images:
            lines.append(f"({len(self.images)} image(s) produced, shown inline)")
        if self.truncated:
            lines.append("(output truncated)")

        if len(lines) == 1:  # only the status line — no captured output
            lines.append("(no output)")
        return "\n".join(lines)

    def to_chat_markdown(self) -> str:
        """Rich text rendering for the Action (images go via a `files` event)."""
        if self.error:
            return f"**Error**\n\n{_fenced(self.error)}"

        # Text only. Images are delivered via a separate `files` event (see the
        # Action/Tool) because Open WebUI renders message `files` regardless of the
        # content-vs-output precedence that hides plain `content` for Responses-API
        # messages; a `![](data:...)` in content would silently not render there.
        # Untrusted output goes through _fenced() so backticks in it can't break
        # out of the code block and render as live markdown.
        parts: list[str] = []
        if self.timed_out:
            parts.append(f"⏱️ **Timed out** after {self._duration_text()}.")
        else:
            parts.append(
                f"**Exit code:** `{self.exit_code}` · **Duration:** {self._duration_text()}"
            )
        if self.images:
            parts.append(f"_{len(self.images)} image(s) shown below._")

        if self.result:
            parts.append(f"**result**\n{_fenced(self.result)}")
        if self.stdout:
            parts.append(f"**stdout**\n{_fenced(self.stdout)}")
        if self.stderr:
            parts.append(f"**stderr**\n{_fenced(self.stderr)}")
        if self.truncated:
            parts.append("_Output was truncated._")
        if not (self.images or self.stdout or self.stderr or self.result):
            parts.append("_No output._")

        return "\n\n".join(parts)

    def image_files(self) -> list[dict]:
        """Images as Open WebUI message `files` entries (renders reliably)."""
        return [{"type": "image", "url": uri} for uri in self.images]


SUPPORTED_LANGUAGES = ("python", "shell")


_PY_RUNNER = """\
import ast
import os

os.makedirs({outdir!r}, exist_ok=True)
with open({codefile!r}) as _f:
    _src = _f.read()
_ns = {{"__name__": "__main__", "__file__": {codefile!r}}}
try:
    _tree = ast.parse(_src)
    _result = None
    if _tree.body and isinstance(_tree.body[-1], ast.Expr):
        _last = _tree.body.pop()
        exec(compile(_tree, {codefile!r}, "exec"), _ns)
        _expr = ast.fix_missing_locations(ast.Expression(_last.value))
        _val = eval(compile(_expr, {codefile!r}, "eval"), _ns)
        if _val is not None:
            _result = repr(_val)[:{maxbytes}]
    else:
        exec(compile(_tree, {codefile!r}, "exec"), _ns)
    if _result is not None:
        with open({resultfile!r}, "w") as _rf:
            _rf.write(_result)
finally:
    try:
        import matplotlib.pyplot as _plt

        for _i, _num in enumerate(_plt.get_fignums()):
            _plt.figure(_num).savefig(os.path.join({outdir!r}, "figure_%02d.png" % _i))
    except Exception:
        pass
"""


@dataclass(frozen=True)
class RunPlan:
    """A concrete plan to run one snippet in a sandbox."""

    argv: tuple[str, ...]
    files: dict[str, str] = field(default_factory=dict)


def normalize_language(language: str | None, default: str = "python") -> str:
    """Map a caller/fence language hint to a supported language."""
    lang = (language or default or "python").strip().lower()
    if lang in ("py", "python3"):
        return "python"
    if lang in ("sh", "bash", "shell", "zsh"):
        return "shell"
    return lang


def build_run_plan(language: str, code: str, max_output_bytes: int = 100_000) -> RunPlan:
    """Build the run plan for a supported language, else raise ``ValueError``."""
    lang = normalize_language(language)
    if lang == "python":
        runner = _PY_RUNNER.format(
            outdir=OUTPUT_DIR,
            codefile=CODE_FILENAME,
            resultfile=RESULT_FILENAME,
            maxbytes=max_output_bytes,
        )
        return RunPlan(
            argv=("python3", RUNNER_FILENAME),
            files={CODE_FILENAME: code, RUNNER_FILENAME: runner},
        )
    if lang == "shell":
        return RunPlan(argv=("bash", "-lc", code))
    raise ValueError(
        f"Unsupported language {language!r}. Supported: {', '.join(SUPPORTED_LANGUAGES)}."
    )


_semaphores: dict[int, asyncio.Semaphore] = {}


def _get_semaphore(limit: int) -> asyncio.Semaphore:
    sem = _semaphores.get(limit)
    if sem is None:
        sem = asyncio.Semaphore(limit)
        _semaphores[limit] = sem
    return sem


@dataclass
class CodeExecutionRequest:
    """A resolved request to execute one snippet."""

    code: str
    language: str
    valves: Valves
    api_key: str  # already-resolved effective key ("" means unconfigured)


def _decode_capped(data: bytes, cap: int) -> tuple[str, bool]:
    """Decode bytes as UTF-8 (multi-byte-safe on truncation), capped at ``cap``."""
    if data is None:
        return "", False
    truncated = len(data) > cap
    if truncated:
        data = data[:cap]
    return data.decode("utf-8", errors="replace"), truncated


async def _collect_images(sandbox: AsyncSandbox) -> list[str]:
    """Read image files from the per-run output dir and return base64 data URIs."""
    try:
        entries = await sandbox.fs.list(OUTPUT_DIR)
    except Exception:
        return []  # dir absent / unreadable — no images

    uris: list[str] = []
    total = 0
    for entry in sorted(entries, key=lambda e: e.path):
        if getattr(entry, "is_dir", False):
            continue
        mime = IMAGE_MIME_TYPES.get(splitext(entry.path)[1].lower())
        if mime is None:
            continue
        # Skip oversized files by their listed size *before* reading them into host
        # memory, so a single huge file can't cause memory pressure.
        size = getattr(entry, "size", 0) or 0
        if size > MAX_IMAGE_BYTES or total + size > MAX_IMAGE_BYTES:
            continue
        try:
            raw = await sandbox.fs.read_bytes(f"{OUTPUT_DIR}/{entry.path}")
        except Exception:
            continue
        total += len(raw)
        if total > MAX_IMAGE_BYTES:
            break
        encoded = base64.b64encode(raw).decode("ascii")
        uris.append(f"data:{mime};base64,{encoded}")
    return uris


async def _run_in_sandbox(sandbox: AsyncSandbox, request: CodeExecutionRequest):
    """Write the code, ensure the output dir, and exec. Returns the CommandResult."""
    plan = build_run_plan(request.language, request.code, request.valves.max_output_bytes)
    # Create the output dir via exec (runs as the sandbox user) rather than the fs
    # RPC (runs as the guest agent / root), so the code can write images into it.
    await sandbox.exec("mkdir", "-p", OUTPUT_DIR)
    for name, content in plan.files.items():
        await sandbox.fs.write_text(name, content)
    return await sandbox.exec(*plan.argv, timeout=request.valves.timeout_seconds)


async def execute(request: CodeExecutionRequest) -> ExecutionResult:
    """Provision a fresh Tenki sandbox, run code, collect output, always tear down."""
    if not request.api_key:
        return ExecutionResult(
            error=(
                "No Tenki API key configured. Set 'tenki_api_key' in the plugin "
                "settings (Valves) or your personal settings (UserValves)."
            )
        )

    try:
        build_run_plan(request.language, request.code)  # validate language early
    except ValueError as err:
        return ExecutionResult(error=str(err))

    valves = request.valves
    async with _get_semaphore(valves.max_concurrent_executions):
        return await _provision_and_run(request)


async def _provision_and_run(request: CodeExecutionRequest) -> ExecutionResult:
    valves = request.valves
    started = time.monotonic()

    try:
        sandbox = await AsyncSandbox.create(
            auth_token=request.api_key,
            base_url=valves.tenki_api_endpoint,  # data goes only to the configured endpoint
            workspace_id=valves.tenki_workspace_id or None,
            cpu_cores=valves.cpu_cores,
            memory_mb=valves.memory_mb,
            disk_size_gb=valves.disk_size_gb,
            allow_outbound=valves.network_egress,  # egress off by default
            image=valves.sandbox_image or None,
            max_duration=valves.timeout_seconds + SANDBOX_LIFETIME_BUFFER,
        )
    except Exception as err:  # provisioning / auth / quota — execution never ran
        return ExecutionResult(error=f"Sandbox provisioning failed: {err}")

    timed_out = False
    exec_result = None
    images: list[str] = []
    result_text = ""
    run_error: str | None = None
    try:
        try:
            exec_result = await asyncio.wait_for(
                _run_in_sandbox(sandbox, request),
                timeout=valves.timeout_seconds + 5,
            )
        except TimeoutError:
            timed_out = True
        except Exception as err:  # SDK/run failure — surface, don't crash the caller
            run_error = f"Execution failed: {err}"
        # Guest-side timeout returns a CommandResult; treat a full-window run as timed out.
        if exec_result is not None and (time.monotonic() - started) >= valves.timeout_seconds - 0.5:
            timed_out = True

        if run_error is None:
            try:
                images = await _collect_images(sandbox)
            except Exception:
                images = []
            try:  # REPL-style last-expression echo (Python runner writes this)
                raw_result = await sandbox.fs.read_text(RESULT_FILENAME)
                # Cap like stdout/stderr so this channel can't bypass max_output_bytes.
                result_text, _ = _decode_capped(raw_result.encode("utf-8"), valves.max_output_bytes)
                result_text = result_text.strip()
            except Exception:
                result_text = ""
    finally:
        try:
            await sandbox.close()  # always released (even on timeout/exception)
        except Exception:
            pass

    duration_ms = int((time.monotonic() - started) * 1000)

    if run_error is not None:
        return ExecutionResult(error=run_error, duration_ms=duration_ms)

    if exec_result is None:  # timed out before any result came back
        return ExecutionResult(
            timed_out=timed_out,
            duration_ms=duration_ms,
            images=images,
        )

    stdout, out_trunc = _decode_capped(exec_result.stdout, valves.max_output_bytes)
    stderr, err_trunc = _decode_capped(exec_result.stderr, valves.max_output_bytes)
    return ExecutionResult(
        stdout=stdout,
        stderr=stderr,
        result=result_text,
        images=images,
        exit_code=exec_result.exit_code,
        duration_ms=duration_ms,
        timed_out=timed_out,
        truncated=out_trunc or err_trunc,
    )


async def _emit_status(emitter, description: str, done: bool) -> None:
    if emitter:
        await emitter({"type": "status", "data": {"description": description, "done": done}})


class Tools:
    Valves = Valves
    UserValves = UserValves

    def __init__(self):
        self.valves = self.Valves()

    async def execute_code(
        self,
        code: str,
        language: str = "python",
        __user__: dict | None = None,
        __event_emitter__=None,
    ) -> str:
        """Execute code in an isolated, ephemeral Tenki microVM sandbox and return its output.

        Use this to run Python or shell code to compute answers, analyze data, or
        produce charts. Each call runs in a fresh sandbox with no state from
        previous calls.

        :param code: The source code to execute.
        :param language: "python" (default) or "shell".
        :return: The captured stdout/stderr/result (and a note if a chart image was produced).
        """
        try:
            key = resolve_effective_key(self.valves, __user__)
            if not key:
                return (
                    "Error: No Tenki API key configured. Set 'tenki_api_key' in the "
                    "plugin settings (Valves) or your personal settings (UserValves)."
                )

            language = normalize_language(language, self.valves.default_language)
            await _emit_status(__event_emitter__, "Provisioning Tenki sandbox…", False)

            request = CodeExecutionRequest(
                code=code,
                language=language,
                valves=self.valves,
                api_key=key,
            )
            result = await execute(request)

            if __event_emitter__ and result.images:
                # Surface images to the user via a `files` event (renders regardless
                # of the content-vs-output precedence for Responses-API messages).
                await __event_emitter__({"type": "files", "data": {"files": result.image_files()}})
            await _emit_status(
                __event_emitter__,
                "Timed out" if result.timed_out else "Done",
                True,
            )
            return result.to_model_text()
        except Exception as err:  # never raise into the model's tool loop
            return f"Error: code execution failed: {err}"
